-import { collectionSummary, reconcileRun, startEditorWorkflow } from "./run-controls";
+import { cancelWorkflow, collectionSummary, exportResearchDataset, reconcileRun, startEditorWorkflow } from "./run-controls";

 describe("run controls IPC boundary", () => {
   it("saves the whole editor root with default scope before starting its saved id", async () => {
     const graph = { blocks: [createBlock("research", { id: "research", position: { x: 0, y: 0 } })], edges: [] };
     const workflow: Workflow = { ...fixtureWorkflow, ...graph, id: "wf_saved", version: 2 };
     const save = vi.fn(async () => workflow);
     const start = vi.fn(async () => { expect(save).toHaveBeenCalledOnce(); return fixtureRun; });
     const onSaved = vi.fn();
     await startEditorWorkflow({ workflows: { save }, runs: { start } }, graph, fixtureScope, "wf_saved", onSaved);
     expect(save).toHaveBeenCalledWith({ id: "wf_saved", name: "Research workflow", scope: fixtureScope, blocks: graph.blocks, edges: graph.edges });
     expect(start).toHaveBeenCalledWith("wf_saved");
     expect(onSaved).toHaveBeenCalledWith(workflow);
   });

   it("never starts when save fails; exposes actionable offline/storage error", async () => {
     const start = vi.fn();
     const save = vi.fn(async () => { throw new Error("Persistence unavailable"); });
     const graph = { blocks: [createBlock("raw", { id: "raw", position: { x: 0, y: 0 } })], edges: [] };
     await expect(startEditorWorkflow({ workflows: { save }, runs: { start } }, graph, fixtureScope)).rejects.toThrow("Persistence unavailable");
     expect(start).not.toHaveBeenCalled();
   });

   it("rejects an invalid or empty root before IPC", async () => {
     const save = vi.fn();
     const client = { workflows: { save }, runs: { start: vi.fn() } };
     await expect(startEditorWorkflow(client, { blocks: [], edges: [] }, fixtureScope)).rejects.toThrow(/Add a block/);
     await expect(startEditorWorkflow(client, { blocks: [], edges: [{ id: "bad", source: "none", sourcePort: "out", target: "missing", targetPort: "in" }] }, fixtureScope)).rejects.toThrow();
     expect(save).not.toHaveBeenCalled();
   });

   it("retains a pushed terminal update when start returns an older running snapshot", () => {
     const completed = { ...fixtureRun, status: "completed" as const };
     expect(reconcileRun(completed, { ...completed, status: "running" })).toBe(completed);
     expect(reconcileRun(completed, { ...completed, id: "run_next", status: "queued" }).status).toBe("queued");
     const paused = { ...completed, status: "waiting_for_review" as const };
     expect(reconcileRun(paused, { ...paused, status: "running" })).toBe(paused);
     expect(reconcileRun(paused, completed)).toBe(completed);
   });

+  it("cancels the active run, including human-review pauses", async () => {
+    const cancelled = { ...fixtureRun, status: "cancelled" as const };
+    const cancel = vi.fn(async () => cancelled);
+    const result = await cancelWorkflow({ runs: { cancel } }, { ...fixtureRun, status: "waiting_for_review" });
+    expect(cancel).toHaveBeenCalledWith(fixtureRun.id);
+    expect(result.status).toBe("cancelled");
+    await expect(cancelWorkflow({ runs: { cancel } }, cancelled)).rejects.toThrow(/Only active runs/);
+    expect(cancel).toHaveBeenCalledOnce();
+  });
+
+  it("exposes cancel errors without pretending cancellation succeeded", async () => {
+    const cancel = vi.fn(async () => { throw new Error("Run service unavailable"); });
+    await expect(cancelWorkflow({ runs: { cancel } }, { ...fixtureRun, status: "running" })).rejects.toThrow("Run service unavailable");
+  });
+
+  it.each(["json", "xlsx", "csv"] as const)("exports %s through the native-dialog IPC contract", async (format) => {
+    const dataset = ResearchDataset.parse({ schemaVersion: 1, runId: fixtureRun.id, sources: [], records: [], results: [], retrievedAt: fixtureRun.startedAt });
+    const research = vi.fn(async () => null);
+    expect(await exportResearchDataset({ exports: { research } }, dataset, format)).toBeNull();
+    expect(research).toHaveBeenCalledWith({ runId: fixtureRun.id, format });
+  });
+
   it.each([
