 import {
   validateGraph,
   WorkflowRun,
   type AgentCollectionResult,
   type ProductScope,
+  type ResearchDataset,
   type ReqflowApi,
   type Workflow,
   type WorkflowGraph,
 } from "@reqflow/core";

 type RunClient = { workflows: Pick<ReqflowApi["workflows"], "save">; runs: Pick<ReqflowApi["runs"], "start"> };

 /** Save the root snapshot, never just the currently open inner workplace. */
 export async function startEditorWorkflow(
   client: RunClient,
   graph: WorkflowGraph,
   scope: ProductScope,
   workflowId?: string,
   onSaved?: (workflow: Workflow) => void,
 ): Promise<WorkflowRun> {
   const issues = validateGraph(graph);
   if (issues.length) throw new Error(`Invalid workflow: ${issues.map((issue) => issue.message).join("; ")}`);
   if (!graph.blocks.length) throw new Error("Add a block before running the workflow.");
   const workflow = await client.workflows.save({
     ...(workflowId ? { id: workflowId } : {}),
     name: "Research workflow",
     scope: structuredClone(scope),
     ...structuredClone(graph),
   });
   onSaved?.(workflow);
   return WorkflowRun.parse(await client.runs.start(workflow.id));
 }

 const settled = new Set(["completed", "failed", "cancelled", "waiting_for_review"]);
 export function isRunBusy(run: WorkflowRun | null): boolean {
   return !!run && (run.status === "queued" || run.status === "running" || run.status === "waiting_for_review");
 }

 /** Main can push completion before start/cancel returns its older snapshot. */
 export function reconcileRun(current: WorkflowRun | null, next: WorkflowRun): WorkflowRun {
   if (current?.id === next.id && settled.has(current.status) && (next.status === "queued" || next.status === "running")) return current;
   return next;
 }

 export function collectionSummary(result: AgentCollectionResult): string {
   switch (result.status) {
     case "blocked": return "Blocked — permission or provider approval required";
     case "missing_credentials": return "No credentials configured";
     case "empty": return "No matching records";
     case "partial": return "Partial collection — review limitations";
     case "error": return "Collection failed";
     case "cancelled": return "Collection cancelled";
     case "success": return "Collection complete";
   }
 }
+
+export async function cancelWorkflow(client: { runs: Pick<ReqflowApi["runs"], "cancel"> }, run: WorkflowRun): Promise<WorkflowRun> {
+  if (!isRunBusy(run)) throw new Error("Only active runs can be cancelled.");
+  const next = WorkflowRun.parse(await client.runs.cancel(run.id));
+  if (next.id !== run.id) throw new Error("Cancellation returned another run.");
+  return next;
+}
+
+export function exportResearchDataset(
+  client: { exports: Pick<ReqflowApi["exports"], "research"> },
+  dataset: ResearchDataset,
+  format: "json" | "xlsx" | "csv",
+): Promise<{ path: string } | null> {
+  return client.exports.research({ runId: dataset.runId, format });
+}

